-- seed/001_core_seed.sql
-- Realistic dev seed data for the Core pillar (docs/07-core-ddl.md).
-- Run via `make seed` (needs DATABASE_URL + NIK_ENCRYPTION_KEY in .env).
-- Idempotent: every row uses a fixed literal id, ON CONFLICT (id) DO NOTHING.
-- Login password for all seeded staff/doctor accounts: Passw0rd123!

BEGIN;

